package ai.nooa.clad; public record VerificationResult(boolean passed, java.util.List<String> checks, java.util.List<String> failures) { public static VerificationResult pass(java.util.List<String> checks) { return new VerificationResult(true, checks, java.util.List.of()); } public static VerificationResult fail(java.util.List<String> checks, java.util.List<String> failures) { return new VerificationResult(false, checks, failures); } }
